import{_ as e,o as s,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Habilidades, límite de puntos y maestros","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/characters/skills.md","filePath":"es/guide/characters/skills.md"}'),r={name:"es/guide/characters/skills.md"};function o(t,a,d,l,c,p){return s(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="skills-skillcap-teachers" tabindex="-1">Habilidades, límite de puntos y maestros <a class="header-anchor" href="#skills-skillcap-teachers" aria-label="Enlace permanente a &quot;Habilidades, límite de puntos y maestros&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> Son cambios previstos, no reglas confirmadas del juego disponible. <strong>Implementación/disponibilidad:</strong> no acreditada para este rediseño. <strong>Verificación:</strong> solo revisión documental. <strong>Revisado:</strong> 2026-10-08 frente a la <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">especificación completa</a>.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Las habilidades aportan capacidad dentro de un presupuesto compartido propuesto de unos 700 puntos / 100 por habilidad.</li><li>Los maestros enseñan los fundamentos al partir de cero; las competencias iniciales pueden incluirlos.</li><li>Importan el trabajo útil al comienzo y los siguientes pasos significativos; las mejoras exactas y los costes de enseñanza siguen abiertos.</li></ul><h2 id="capability-within-a-shared-budget" tabindex="-1">Capacidad dentro de un presupuesto compartido <a class="header-anchor" href="#capability-within-a-shared-budget" aria-label="Enlace permanente a &quot;Capacidad dentro de un presupuesto compartido&quot;">​</a></h2><p>La dirección actual es de aproximadamente <strong>700 puntos totales de habilidad</strong> y <strong>100 de máximo normal</strong>, sin una subida ordinaria a 120. Son objetivos de diseño, no ajustes confirmados del servidor. Invertir profundamente debe aportar una capacidad diferenciada y dejar espacio para habilidades de apoyo útiles.</p><h2 id="useful-at-every-stage" tabindex="-1">Utilidad en cada etapa <a class="header-anchor" href="#useful-at-every-stage" aria-label="Enlace permanente a &quot;Utilidad en cada etapa&quot;">​</a></h2><p>Los principiantes deben realizar trabajos sencillos con consistencia. Los personajes competentes adquieren fundamentos fiables; los hábiles contribuyen a grupos; los profesionales afrontan situaciones avanzadas; los expertos interpretan más y trabajan con consistencia; los maestros alcanzan la máxima competencia técnica. Son bandas aproximadas, no un catálogo de desbloqueos rígidos.</p><p>Las mejoras iniciales deben ser rápidas, la progresión ordinaria sustancial y el tramo final hasta 100 lento y significativo. Alcanzar habilidades relevantes alrededor de 40–60 durante el primer día es una aspiración que depende de la actividad y la configuración, no un calendario prometido.</p><h2 id="learning-skills-and-finding-teachers" tabindex="-1">Aprender habilidades y encontrar maestros <a class="header-anchor" href="#learning-skills-and-finding-teachers" aria-label="Enlace permanente a &quot;Aprender habilidades y encontrar maestros&quot;">​</a></h2><p>Al partir exactamente de cero, el personaje generalmente necesita fundamentos de un maestro, academia, gremio, instructor o especialista. La enseñanza podría elevar la habilidad a unos 5–10 o desbloquear esos fundamentos de otra forma. Después se sigue aprendiendo mediante práctica, exploración y uso. Las competencias iniciales son una excepción: los <a href="/Syrolands-Public/es/guide/characters/character-creation.html">trasfondos</a> pueden aportar ya los fundamentos alrededor de habilidad 20.</p><p>Los costes, la disponibilidad de maestros y las tasas exactas de mejora siguen abiertos. Esta documentación no ha añadido ningún requisito de enseñanza al juego en funcionamiento.</p><h2 id="know-what-training-offers" tabindex="-1">Saber qué aporta entrenar <a class="header-anchor" href="#know-what-training-offers" aria-label="Enlace permanente a &quot;Saber qué aporta entrenar&quot;">​</a></h2><p>Debes poder ver tus capacidades actuales y siguientes pasos significativos. El trabajo rutinario de poca dificultad no debe provocar fallos constantes; una habilidad mayor amplía la dificultad que puedes afrontar. Esta claridad no revela todas las recetas ocultas, técnicas ni interacciones secretas.</p><p><a href="/Syrolands-Public/es/guide/characters/progression.html">Progresión del personaje</a> · <a href="/Syrolands-Public/es/guide/characters/techniques.html">Técnicas aprendidas</a></p>',15)])])}const h=e(r,[["render",o]]);export{m as __pageData,h as default};
